// Obtener la respuesta del nodo anterior
const data = $input.all()[0].json;

// Mapear columnas a índices para convertir filas a objetos
const table = data.tables[0];
const columns = table.columns.map(col => col.name);
const rows = table.rows;

const errors = rows.map(row =>
  Object.fromEntries(columns.map((col, i) => [col, row[i]]))
);

if (!errors.length) {
  return [{ json: { skip: true, message: "No hay errores en los últimos 15 minutos" } }];
}

// Agrupar por cloud_RoleInstance y tipo de error
const grouped = {};
for (const error of errors) {
  const instance = error.cloud_RoleInstance || 'Unknown';
  const errorType = error.type || 'Unknown';
  if (!grouped[instance]) grouped[instance] = {};
  if (!grouped[instance][errorType]) grouped[instance][errorType] = [];
  grouped[instance][errorType].push(error);
}

const totalErrors = errors.length;

// ── Teams (MessageCard) ──────────────────────────────────────────────────────
function buildTeamsPayload(grouped, total) {
  const sections = [];
  for (const instance of Object.keys(grouped).sort()) {
    for (const errorType of Object.keys(grouped[instance]).sort()) {
      const errs = grouped[instance][errorType];
      const first = errs[0];
      const shortType = errorType.split('.').at(-1);
      const message = first.innermostMessage || first.outerMessage || first.message || 'Sin mensaje';
      sections.push({
        activityTitle: `🔴 [${instance}] **${shortType}** — ${errs.length} ocurrencia(s)`,
        activitySubtitle: `Instancia: \`${instance}\` | Servicio: \`${first.cloud_RoleName || '-'}\``,
        activityText: message.substring(0, 300),
        facts: [
          { name: "Tipo completo", value: errorType },
          { name: "Operación",     value: first.operation_Name || '-' },
          { name: "Último visto",  value: first.timestamp || '-' },
        ]
      });
    }
  }
  return {
    "@type": "MessageCard",
    "@context": "http://schema.org/extensions",
    themeColor: "FF0000",
    summary: `${total} errores detectados`,
    title: `⚠️ ${total} errores en los últimos 15 min — Application Insights`,
    sections
  };
}

// ── Discord (Webhook con embeds) ─────────────────────────────────────────────
function buildDiscordPayload(grouped, total) {
  const embeds = [];
  for (const instance of Object.keys(grouped).sort()) {
    for (const errorType of Object.keys(grouped[instance]).sort()) {
      const errs = grouped[instance][errorType];
      const first = errs[0];
      const shortType = errorType.split('.').at(-1);
      const message = first.innermostMessage || first.outerMessage || first.message || 'Sin mensaje';
      embeds.push({
        title: `🔴 [${instance}] ${shortType} × ${errs.length}`,
        description: message.substring(0, 300),
        color: 15158332,
        fields: [
          { name: "Instancia",      value: instance,                          inline: true  },
          { name: "Servicio",       value: first.cloud_RoleName || '-',       inline: true  },
          { name: "Operación",      value: first.operation_Name || '-',       inline: false },
          { name: "Tipo completo",  value: `\`${errorType}\``,                inline: false },
          { name: "Último registro",value: first.timestamp || '-',            inline: false },
        ],
        footer: { text: "Application Insights Alert" }
      });
    }
  }
  return {
    username: "Application Insights",
    content: `@here ⚠️ **${total} errores detectados en los últimos 15 minutos**`,
    embeds: embeds.slice(0, 10) // Discord permite máximo 10 embeds por mensaje
  };
}

return [{
  json: {
    teams:       buildTeamsPayload(grouped, totalErrors),
    discord:     buildDiscordPayload(grouped, totalErrors),
    error_count: totalErrors,
    skip:        false
  }
}];

